#!/usr/bin/env python3
"""Keep a host's Flutter ARB API aligned with the shared Git message contract.

Only the English template catalog and the small generated host adapter are
written. Translations stay in the application's existing ARB files and Flutter
continues to generate its localization classes. No runtime catalog is added.
"""
import argparse
import json
import pathlib
import re
import sys


def render_adapter(messages, class_name, import_uri, named):
    lines = [
        '// Generated by busystack_git_flutter/tool/sync_host_localizations.py.',
        '// Translations belong to this application’s existing Flutter ARB catalog.',
        "import 'package:busystack_git_flutter/busystack_git_flutter.dart' show GitMessages;",
        f"import '{import_uri}';",
        '',
        f'extension SharedGitLocalizations on {class_name} {{',
        '  String translateSharedGitMessage(String message, Map<String, Object?> values) => switch (message) {',
    ]
    for name, template in messages.items():
        key = 'gitUi' + name[0].upper() + name[1:]
        parameters = list(dict.fromkeys(re.findall(r'\{([A-Za-z][A-Za-z0-9_]*)\}', template)))
        arguments = ', '.join((parameter + ': ' if named else '') +
                              f"(values['{parameter}'] ?? '').toString()"
                              for parameter in parameters)
        method = key + ('(' + arguments + ')' if parameters else '')
        lines.append(f'    GitMessages.{name} => {method},')
    lines.extend(['    _ => message,', '  };', '}', ''])
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--arb', type=pathlib.Path, required=True)
    parser.add_argument('--adapter', type=pathlib.Path, required=True)
    parser.add_argument('--class-name', required=True)
    parser.add_argument('--import-uri', required=True)
    parser.add_argument('--named', action='store_true')
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    raw = json.loads((pathlib.Path(__file__).parent / 'git_messages.json').read_text())
    messages = {}
    seen = set()
    for name, template in raw.items():
        if template not in seen:
            messages[name] = template
            seen.add(template)
    arb = json.loads(args.arb.read_text())
    failures = []
    for name, template in messages.items():
        key = 'gitUi' + name[0].upper() + name[1:]
        parameters = list(dict.fromkeys(re.findall(r'\{([A-Za-z][A-Za-z0-9_]*)\}', template)))
        metadata = {'description': 'Shared Git interface: ' + template.split('\n')[0]}
        if parameters:
            metadata['placeholders'] = {value: {'type': 'String'} for value in parameters}
        if args.check and (arb.get(key) != template or arb.get('@' + key) != metadata):
            failures.append(key)
        arb[key] = template
        arb['@' + key] = metadata
    adapter = render_adapter(messages, args.class_name, args.import_uri, args.named)
    if args.check:
        # Dart format only changes whitespace outside string literals here.
        def compact(source):
            return re.sub(r'[\s,]+', '', source)
        if not args.adapter.exists() or compact(args.adapter.read_text()) != compact(adapter):
            failures.append(str(args.adapter))
        if failures:
            sys.exit('Git localization API is stale: ' + ', '.join(failures))
    else:
        args.arb.write_text(json.dumps(arb, ensure_ascii=False, indent=2) + '\n')
        args.adapter.write_text(adapter)


if __name__ == '__main__':
    main()
